   "orig": "不过，还有些问题会让知情的读者不安，而且只就经典动力学而论。就单个粒子及其伴随的场而言，经典力学中的亚微观动力学确实具有时间反演对称性。但在实践中，人们对系统各个成分的行为所知甚少。要掌握每个粒子的确切位置和动量，通常既做不到、也没必要；系统的总体行为，用个体粒子物理参数的某些适当平均值就足以描述。这类参数诸如质量、动量和能量的分布，质心的位置与速度，各处的温度和压强，弹性性质，转动惯量，整体的详细形状及其在空间中的取向，等等。于是有个重要问题：在实践中，对这些平均的「整体」参数有良好的初始了解，是否足以把系统的动力学行为确定到令人满意的程度？",
