   "orig": "让我们更确切地看看第二定律究竟说了什么。作为预备，我应当先交代热力学第一定律。第一定律只是说：任何孤立系统的总能量守恒。读者很可能抱怨这算不上新东西（18.6 节、20.4 节、21.4 节）。但在这条定律被提出时（最初由萨迪·卡诺在 1820 年代早期提出，不过他并未发表），人们此前并不清楚热只是能量的一种形式——就连通常的宏观能量概念本身也还没有完全廓清。第一定律明确说出：比如一个物体因空气阻力而减速、失去动能（18.6 节）时，总能量并没有丢，因为这份能量只是被用来加热空气和物体本身。这种热能（主要）被理解为空气分子运动的动能，以及物体内部粒子振动的动能。再者，温度不过是每个自由度分到多少能量的量度，所以热和温度这些热力学概念，基本上就是早先已懂的动力学概念用到材料的单个成分上、并以统计方式处理的结果。第一定律具有我们熟悉的那种精确性：某个量——总能量——保持不变，尽管其间可能有各种各样复杂的过程在进行。过程之后的总能量，等于过程之前的总能量。",
