   "h": "27.8 黑洞",
   "orig": "黑洞是什么？粗略地说，它是时空的一个区域，由物质向内引力坍缩形成，那里的引力强到连光都逃不出去。要直观理解这种局面怎么会发生，想想牛顿的逃逸速度。若一块石头以某个速度 v 从地面向上抛出，它到达某个高度后会落回地面；这个高度正是石头的动能全部用于克服地面以上引力势能的高度（18.6 节）。离地高度完全取决于抛射速度（不计空气阻力）。然而，当速度超过 (2GM/R)^(1/2)——称为逃逸速度——时，石头就会彻底逃离地球的引力场。（这里 M、R 分别是地球的质量和半径，G 是牛顿引力常数。）现在设想用一个质量大得多、集中得多的天体替代地球。逃逸速度会更大（M 增大、R 减小时 M/R 都会上升），我们可以设想质量与集中程度大到表面处的逃逸速度甚至超过光速。",
