   "h": "27.8 黑洞（续）",
   "orig": "那么接着会发生什么？回到那颗大质量恒星，比如说 10M☉，假定它起初温度足够高，热压强足以支撑。可随着恒星冷却，某个阶段其受压的核心会超过钱德拉塞卡极限，于是坍缩。外层的坠落可能触发一次猛烈爆发，称为超新星。这类爆发恒星常被观测到，主要在其他星系；超新星在几天之内就能让它所在的整个星系黯然失色。但若这样的爆发没有抛掉足够的物质——对一颗初始 10M☉ 的恒星来说，损失那么多不太可能——那么预期确实就是：恒星将无法阻挡地坍缩，直到到达米歇尔那套考虑适用的尺度。让我们看图 27.11，那是一幅描绘坍缩成黑洞的时空图。（当然，有一个空间维不得不省掉。）我们看到物质继续向内坍缩，穿过那个表面——称为（绝对）事件视界——在那里逃逸速度真的等于光速。此后，来自恒星本身的任何进一步信息都到不了任何外部观测者，一个黑洞就形成了。",
