   "orig": "先看观测情形。黑洞存在的证据有没有？确实有。1970 年代，人们已知若干奇特的双星系统，其中只有一颗在可见光下发亮。另一颗的存在、质量和运动，是从其可见伴星运动的精细细节推断出来的。而且，从邻近区域发出的 X 射线信号推断出，那颗看不见的伴星是个致密天体，其质量太大，不可能是公认物理原理所允许的两种致密星——白矮星或中子星——中的任何一种。X 射线的发射也与这样一幅图像相符：不可见天体是黑洞，周围环绕着所谓的「吸积盘」——气体和尘埃组成的盘螺旋着越靠越近、以越来越大的速度冲向黑洞，越接近中心被加热得越厉害。物质真正落入黑洞之前，会先发出 X 射线（见图 27.12a）。这些黑洞候选者中最著名（也是当时观测上最有说服力）的是 X 射线源天鹅座 X-1，那颗致密而黑暗的成员质量约为 7M☉，按公认理论这肯定排除了它是白矮星或中子星的可能。",
