   "orig": "我在图 27.11 中画了一些零锥，好让时空的因果性质比较清楚。最本质的特征是黑洞事件视界的存在，它在时空中是一张三维曲面 H。如 27.8 节所说，它有这样一个性质：源自 H 内部区域的任何信号都逃不到外部区域。可以看出这是锥向内倾倒的效果——它们恰好与 H 相切。任何从 H 内侧穿到外侧的世界线，都不得不违反锥所定义的因果性（17.7 节）。我描绘的是引力坍缩完全球对称的情形，这是 J. 罗伯特·奥本海默与哈特兰·斯奈德（1939）最初研究的情形，用施瓦茨席尔德几何描述内落物质外部的区域。",
