   "h": "27.11 宇宙学（续）",
   "orig": "基本上，FLRW 模型的特征是空间上完全均匀且各向同性。粗略地说，各向同性意味着宇宙在每个方向上看都一样，所以它有 O(3) 旋转对称群。而空间均匀意味着在任一时刻，宇宙在空间每一点看都一样；相应地，存在一个对称群，它在一族类空三维曲面（即时刻 t 的空间曲面 Tₜ）的每个成员上都是可迁的（18.2 节）（合起来给出 6 维对称群）。这一对假定，与对大尺度物质分布的观测、以及微波背景的性质相当吻合。空间各向同性被直接发现是极好的近似（来自对极遥远源的观测，主要来自 2.7 K 辐射）。此外，如果宇宙不均匀，那它只能从非常特殊的地方看起来各向同性；所以除非宇宙同时也均匀，我们就得身处一个非常优越的位置，宇宙才显得各向同性。当然，观测上的各向同性并不严格，因为我们只在某些方向上看到单个星系、星系团和超星系团。还有规模骇人的物质不均匀分布，且并不总看得见，比如所谓的巨大吸引子，它似乎不仅在拉我们自己的星系，还在拉几个邻近的星系团。但情况似乎是：我们看得越远，对特定空间不均匀性的偏离就按比例越小。关于我们可及宇宙最遥远区域的最好信息，来自 2.7 K 黑体背景辐射。COBE、BOOMERANG 和 WMAP 等数据告诉我们，尽管在那个尺度上存在极轻微的、十万分之几的偏离，各向同性得到了很好的支持。",
